    "value": true,
    "status": "inferred",
    "reason": "The benchmark explicitly targets scientific software engineering, requiring agents to preserve scientific contracts such as units, coordinate systems, numerical invariants, physical assumptions, and domain-specific workflows. Its objective is to evaluate whether coding agents can resolve engineering tasks while maintaining scientific validity, which constitutes a contribution to AI for Science.",
    "evidence": [
      {
        "source_id": "science_pdf",
        "quote": "SWE-bench Science: Can Coding Agents Resolve Engineering Tasks in Science?",
        "locator": "title"
      },
      {
        "source_id": "science_pdf",
        "quote": "failures in scientific code capable of compromising not only program behavior but also the evidence underlying scientific conclusions.",
        "locator": "abstract"
      },
      {
        "source_id": "science_readme",
        "quote": "Scientific software is full of contracts that ordinary code benchmarks rarely expose: units, coordinate systems, numerical invariants, file-format semantics, physical assumptions, and domain-specific workflows.",
        "locator": "Why This Benchmark section"
      }
    ]
  },
  "scientific_tasks": {
    "value": [
      "Issue-driven repair of real bugs while preserving scientific semantics",
      "Expert-exploratory autonomous reasoning about unknown scientific root causes",
      "Engineering-integration cross-module completion of end-to-end scientific workflows"
    ],
    "status": "source_supported",
    "evidence": [
      {
        "source_id": "science_pdf",
        "quote": "Each task is organized into one of three paradigms: Issue-driven, Expert-exploratory, and Engineering-integration.",
        "locator": "abstract"
      },
      {
        "source_id": "science_pdf",
        "quote": "Issue-driven tasks focus on repairing known defects; Expert-exploratory tasks focus on autonomously reasoning about unknown root causes in scientific scenarios; Engineering-integration tasks focus on understanding architecture across files and connecting a complete multi-module capability chain.",
        "locator": "Section 4.1"
      }
    ]
  },
  "disciplines": {
    "value": [
      "Chemistry",
      "Materials Science and Engineering",
      "Biology",
