    "status": "source_supported",
    "evidence": [
      {
        "source_id": "science_pdf",
        "quote": "1. Source Sampling and Screening. We collect real issues, pull requests (PRs), commit records, and related literature from candidate open-source scientific-computing repositories.",
        "locator": "Section 4 Figure 4"
      }
    ]
  },
  "construction": {
    "value": [
      "Source sampling and screening",
      "Snapshot freezing and reproduction",
      "Public-material abstraction and information isolation",
      "Hidden oracle and counter-calibration",
      "Class-specific task re-design for Issue-driven, Expert-exploratory, and Engineering-integration paradigms"
    ],
    "status": "source_supported",
    "evidence": [
      {
        "source_id": "science_pdf",
        "quote": "All raw tasks are first generated according to a unified and auditable four-stage construction process.",
        "locator": "Section 4"
      },
      {
        "source_id": "science_pdf",
        "quote": "1. Source Sampling and Screening. ... 2. Snapshot Freezing and Reproduction. ... 3. Public-Material Abstraction and Information Isolation. ... 4. Hidden Oracle and Counter-Calibration.",
        "locator": "Figure 4"
      },
      {
        "source_id": "science_pdf",
        "quote": "Raw tasks are further re-designed according to their fit with the three task paradigms.",
        "locator": "Section 4"
      }
    ]
  },
  "ground_truth": {
    "value": "Reference and alternative-valid patches, private tests, contract labels, scientific-rationale and localization support blocks, expected files, source and difficulty metadata.",
    "status": "source_supported",
    "evidence": [
      {
        "source_id": "science_pdf",
        "quote": "Evaluator-only fields include private tests, contract labels, reference and alternative-valid patches, scientific-rationale and localization support blocks, expected files, source and difficulty metadata, contamination tier, and post-hoc annotations.",
        "locator": "Section 3.1"
      }
    ]
  },
  "evaluation": {
    "value": "Patch submission into clean evaluator container with public and private tests; metrics include PublicScore, PrivateScore, Fail2Pass, Pass2Pass, and Pass@1 (exact private-test success).",
    "status": "source_supported",
    "evidence": [
      {
        "source_id": "science_pdf",
        "quote": "Private tests are mounted only after patch submission in a separate evaluator container.",
        "locator": "Section 3.1"
      },
      {
        "source_id": "science_pdf",
        "quote": "For each task–attempt, PublicScore is the mean score across all applicable public test cases, and PrivateScore is the corresponding mean across private test cases. Fail2Pass is the fraction of previously failing private tests that pass after the repair, while Pass2Pass is the fraction of previously passing private tests that remain passing; Pass@1 is a binary exact-private-success measure that equals 1 only when every applicable private test passes.",
        "locator": "Section 5 Evaluation"
      }
    ]
  },
